data.sim-bridge.json5:
{
  plugins: { ros2dds: { allow: { publishers: [".*/camera/color/image_compressed", ".*/camera/depth/image_compressed", ".*/camera/color/camera_info", ".*/tf", ".*/tf_static", ".*/camera/capture_trace", ".*/camera/compression_trace", ".*clock"], subscribers: [] } } },
  mode: "client",
  connect: { endpoints: ["tcp/semantic-s3-router:17448"], exit_on_failure: false },
  scouting: { multicast: { enabled: false } }
}

data.inference-bridge.json5:
{
  plugins: { ros2dds: { allow: { publishers: [], subscribers: [".*/camera/color/image_compressed", ".*/camera/depth/image_compressed", ".*/camera/color/camera_info", ".*/tf", ".*/tf_static", ".*/camera/capture_trace", ".*/camera/compression_trace", ".*clock"] } } },
  mode: "client",
  connect: { endpoints: ["tcp/semantic-s3-router:17448"], exit_on_failure: false },
  scouting: { multicast: { enabled: false } }
}

args:
export HOME=/tmp/ros-home ROS_LOG_DIR=/tmp/ros-home/.ros/log; mkdir -p "$ROS_LOG_DIR"; source /opt/ros/jazzy/setup.bash; source /opt/rmf_demos_ws/install/setup.bash; for attempt in {1..90}; do
  color_info=$(ros2 topic info /robot_1/camera/color/image_raw 2>/dev/null || true);
  depth_info=$(ros2 topic info /robot_1/camera/depth/image_raw 2>/dev/null || true);
  if printf '%s' "$color_info" | grep -q 'Publisher count: 1' && printf '%s' "$depth_info" | grep -q 'Publisher count: 1'; then break; fi;
  sleep 1;
done; exec python3 /opt/semantic-navigation/camera_compressor.py
